ssize_t llistxattr(const char *path, char *list, size_t size);
ssize_t flistxattr(int fd, char *list, size_t size);

// 1. Determine total buffer size needed (size=0)
ssize_t required_sz = listxattr("/path/file", NULL, 0);

if (required_sz > 0) {
    char *buffer = malloc(required_sz);

    // 2. Retrieve list of attribute names (null-separated)
    ssize_t actual_sz = listxattr("/path/file", buffer, required_sz);

    if (actual_sz == -1) { /* Error */ }

    free(buffer);
}
